**פתרון רשמי** (23A-A עמ' 2). הנימוק:
ידוע שהמערך בגודל זוגי ממוין ובו כל האיברים אפשר לחלק לזוגות כך שסכום האיברים בכל הזוגות שווה זה לזה. מזה נובע שהזוגות האלה תופסים מקומות 0 ו-`size-1`, 1 ו-`size-2`, וכללי: כל זוג תופס מקומות `(i, size-1-i)`. לכן אם נחליף בין מקום 1 ו-`size-1` נקבל כבר **שני** זוגות מסודרים בקצוות של המערך: בשני מקומות ראשונים ובשני מקומות אחרונים. לכן אחרי ההחלפה הראשונה נשאר לסדר מערך ממקום 2 עד `size-3`. כך על ידי `size/4` החלפות נסדר כל המערך.
**פתרון:**
```c
void sortpairs(int* a, int size)
{
    int i;
    for (i = 1; i < size/2 ; i += 2)
        swap(a + i, a + size - i);
}
```
**אותו רעיון בצורה אחרת:**
```c
void sortpairs(int* a, int size)
{
    int low = 1, high = size - 1;
    while (low < high-1 ) {
        swap(a + low, a + high);
        low += 2;
        high -= 2;
    }
}
```
**רעיון אחר:**
```c
void sortpairs_2(int* a, int size)
{
    int i,sum=a[0]+a[size-1];
    for (i = 0; i < size-1; i += 2) {
        a[i + 1] = sum-a[i];
    }
}
```

**פתרון רשמי** (23A-A עמ' 3), עם אינדקסים:
```c
void squeeze(char* str)
{
    int i, pos = 0;
    int count[26] = { 0 };
    int len = strlen(str);
    for (i = 0; i < len; ++i)
        count[str[i] - 'a']++;
    for (i = 0; i < len; ++i){
        if (count[str[i] - 'a'] == 3)
        {
            str[pos++] = str[i];
            count[str[i] - 'a'] = 0;
        }
    }
    str[pos] = '\0';
}
```
**פתרון עם מצביעים:**
```c
void squeeze(char* str)
{
    int count[26] = { 0 };
    char* temp = str;
    while (*temp)
        count[*temp++ - 'a']++;
    temp = str;
    while (*temp)
        if (count[*temp++ - 'a'] == 3)
        {
            *str = *(temp - 1);
            count[*str++ - 'a'] = 0;
        }
    *str = '\0';
}
```

**פתרון רשמי** (23A-A עמ' 4-5), פתרון רגיל (הפונקציה `binary_search` היא פונקציית עזר שמחזירה את האינדקס של `num` במערך):
```c
int* distsort_2(int* a, int n, int num)
{
    int idx_num = binary_search(a, n, num);
    int idx_smaller = idx_num - 1, idx_larger = idx_num + 1, new_pos = 1;
    int* new_sort = (int*)malloc(n * sizeof(int));
    assert(new_sort);
    new_sort[0] = num;
    while (0 <= idx_smaller && idx_larger < n) {
        if (a[idx_larger] - num < num - a[idx_smaller]) {
            new_sort[new_pos++] = a[idx_larger++];
        }
        else
            new_sort[new_pos++] = a[idx_smaller--];
    }
    while (0 <= idx_smaller) {
        new_sort[new_pos++] = a[idx_smaller--];
    }
    while (idx_larger < n) {
        new_sort[new_pos++] = a[idx_larger++];
    }
    return new_sort;
}
```
**פתרון יותר יעיל ואלגנטי** (אין צורך בחיפוש מקום של `num` במערך, מתחיל למלא מערך חדש מהסוף):
```c
int* distsort(int* a, int n, int num)
{
    int first = 0, last = n - 1, new_position = n - 1;
    int* new_sort = (int*)malloc(n * sizeof(int));
    assert(new_sort);
    while (first <= last) {
        if (a[last] - num >= num - a[first]) {
            new_sort[new_position--] = a[last--];
        }
        else
            new_sort[new_position--] = a[first++];
    }
    return new_sort;
}
```

**פתרון רשמי** (23A-A עמ' 6):
```c
int waterfill(int valley[R][C], int cloudR, int cloudC, int cloudH) {
    if (cloudH <= valley[cloudR][cloudC])
        return 0;
    int fill = cloudH - valley[cloudR][cloudC];
    valley[cloudR][cloudC] = 255; //Mark not to return
    return fill +
        waterfill(valley, cloudR - 1, cloudC, cloudH) +
        waterfill(valley, cloudR + 1, cloudC, cloudH) +
        waterfill(valley, cloudR, cloudC - 1, cloudH) +
        waterfill(valley, cloudR, cloudC + 1, cloudH);
}
```
**פתרון מתוחכם ללא משתנה עזר:**
```c
int waterfill2(int valley[R][C], int cloudR, int cloudC, int cloudH) {
    if (cloudH <= valley[cloudR][cloudC])
        return 0;
    valley[cloudR][cloudC] += 255; //Mark not to return

    return 255 + cloudH - valley[cloudR][cloudC] +
        waterfill2(valley, cloudR - 1, cloudC, cloudH) +
        waterfill2(valley, cloudR + 1, cloudC, cloudH) +
        waterfill2(valley, cloudR, cloudC - 1, cloudH) +
        waterfill2(valley, cloudR, cloudC + 1, cloudH);
}
```
